-- supabase/migrations/0004_seed_j13_content.sql
-- STATUS: active | UPDATED: 2026-08-02
-- Seeds the 13 master steps and their knowledge checks from the extracted
-- 2026 manuals (generated from src/content/steps.json + manager.json).
-- Idempotent: steps upsert on number; questions are replaced per step.
-- Requires 0003_j13_content_model.sql. Run as: paste into the Supabase SQL
-- editor for project fiowfatqsqagehngburd, or via MCP once re-authorized.

begin;


-- Step 1: Meet & Greet
insert into public.steps (number, slug, title, purpose, content, manager_content)
values (1, 'meet-and-greet', 'Meet & Greet', 'Create a professional first impression, lower resistance and establish a clear next step.', '{"purpose": "Create a professional first impression, lower resistance and establish a clear next step.", "learn": [{"heading": "What Success Looks Like", "body": "Approach promptly without crowding the customer. Use a consistent introduction that earns the customer''s name and purpose. Transition naturally into Interview & Discovery. Recognize body-language and pace cues without surrendering leadership."}, {"heading": "Execution Checklist", "body": "Prepare: visible name badge, professional appearance, phone put away and awareness of arriving customers. Approach with a smile, open posture and appropriate pace. Welcome the customer and introduce yourself. Ask for the customer''s name and use it once in the next sentence. Clarify whether the visit is for sales, service, parts, a specific person or a scheduled appointment. If it is a sales opportunity, set the agenda and lead to Interview & Discovery. If it belongs to another department, personally escort and introduce the customer whenever practical."}, {"heading": "Self-Coaching", "body": "Watch for waiting too long to acknowledge the customer; use a brief welcome immediately, even when finishing another task. Watch for opening with \"What can I sell you?\" or a price question; start with the customer and purpose, not the transaction. Watch for handing the customer off without an introduction; escort, introduce and transfer useful context. Watch for letting \"just looking\" end the conversation; accept the statement, then ask one low-pressure discovery question."}], "wordTracks": [{"label": "Initial welcome", "text": "Good morning, welcome to [Dealership]. I''m [Name]. And you are?"}, {"label": "Purpose", "text": "It''s good to meet you, [Customer]. What brings you in today?"}, {"label": "Sales transition", "text": "Great. I''d like to learn what is most important to you first, and then I''ll help you narrow this down. Follow me."}, {"label": "Just looking", "text": "That''s completely fine. Let''s make your looking productive. What category or use brought you in?"}, {"label": "Appointment", "text": "Welcome back, [Customer]. We were expecting you. Let me get [Name] and make sure the unit is ready."}], "practice": [{"title": "Practice Lab: The Customer Who Wants Space", "instructions": "The customer enters slowly, avoids eye contact and says, \"We''re just looking.\" The salesperson must welcome them, reduce pressure and earn one discovery question. Success standard: customer gives a name, salesperson does not argue with \"just looking\", conversation advances to a use or category question and there is no price promise or product dump."}], "commitment": "On my next customer, I will apply this specific behavior."}'::jsonb, '{"number": 1, "managerCheckpoints": ["Observe whether every arriving customer is acknowledged promptly", "Listen for a complete introduction and a transition question", "Coach the salesperson who stays behind the desk or uses a passive let me know"], "coachingNotes": ["Use a brief welcome immediately, even when finishing another task", "Start with the customer and purpose, not the transaction. Never open with What can I sell you or a price question", "Escort, introduce and transfer useful context instead of handing the customer off without an introduction", "Accept just looking, then ask one low-pressure discovery question instead of letting it end the conversation", "Prompt does not mean aggressive. Acknowledge the customer quickly, then match their pace", "Debrief role-play by asking what created trust, where the salesperson advanced too quickly and what exact phrase should be repeated or replaced. End with one behavior each participant will apply on the next customer"], "roleplayLabs": [{"title": "The Customer Who Wants Space", "scenario": "The customer enters slowly, avoids eye contact and says We''re just looking. The salesperson must welcome them, reduce pressure and earn one discovery question. Roles: salesperson, customer and observer scoring pace, posture and transition.", "evaluationCriteria": ["Customer gives a name", "Salesperson does not argue with just looking", "Conversation advances to a use or category question", "No price promise or product dump"]}], "signoffCriteria": ["Approaches promptly without crowding the customer", "Uses a consistent introduction that earns the customer''s name and purpose", "Transitions naturally into Interview and Discovery", "Recognizes body-language and pace cues without surrendering leadership"]}'::jsonb)
on conflict (number) do update set
  slug = excluded.slug,
  title = excluded.title,
  purpose = excluded.purpose,
  content = excluded.content,
  manager_content = excluded.manager_content,
  version = public.steps.version + 1,
  updated_at = now();

delete from public.knowledge_check_questions
  where step_id = (select id from public.steps where number = 1);

insert into public.knowledge_check_questions (step_id, position, question, options, answer_index)
values ((select id from public.steps where number = 1), 0, 'What is the first commitment you are trying to earn in the Meet & Greet?', '["The customer''s name and the purpose of their visit", "A commitment to buy a unit today", "An agreement on a monthly payment range", "Permission to appraise their trade"]'::jsonb, 0);

insert into public.knowledge_check_questions (step_id, position, question, options, answer_index)
values ((select id from public.steps where number = 1), 1, 'How should you respond when the customer says "I''m just looking"?', '["Give them your card and let them browse alone", "Explain that looking without a salesperson wastes their time", "Accept the statement, then ask one low-pressure discovery question", "Offer a discount to spark their interest"]'::jsonb, 2);

insert into public.knowledge_check_questions (step_id, position, question, options, answer_index)
values ((select id from public.steps where number = 1), 2, 'What is the difference between prompt and aggressive in the approach?', '["Prompt means running to the customer while aggressive means walking", "Prompt means acknowledging the customer immediately while aggressive means crowding or pressuring them", "There is no difference, both mean approaching quickly", "Prompt applies to appointments and aggressive applies to walk-ins"]'::jsonb, 1);

insert into public.knowledge_check_questions (step_id, position, question, options, answer_index)
values ((select id from public.steps where number = 1), 3, 'A customer arrives for a service visit. What does the Meet & Greet standard call for?', '["Point them toward the service department and return to the floor", "Try to convert the visit into a sales opportunity first", "Ask them to wait while you finish with other customers", "Personally escort and introduce the customer whenever practical"]'::jsonb, 3);


-- Step 2: Interview & Discovery
insert into public.steps (number, slug, title, purpose, content, manager_content)
values (2, 'interview-and-discovery', 'Interview & Discovery', 'Understand the customer''s use, priorities, timing, decision process and ownership goals before selecting a unit.', '{"purpose": "Understand the customer''s use, priorities, timing, decision process and ownership goals before selecting a unit.", "learn": [{"heading": "What Success Looks Like", "body": "Conduct a conversational needs assessment. Capture useful notes without making the customer feel interrogated. Identify use, users, priorities, trade, timing and purchase structure. Summarize the discovery and earn permission to select a unit."}, {"heading": "Execution Checklist", "body": "Set the agenda: explain that a few questions will help avoid wasting time. Start broad: what brought the customer in and what are they hoping to accomplish? Understand current ownership: what they use now, what works and what needs to improve. Identify primary use, additional users, terrain, towing, payload, passengers, storage, travel or job requirements. Prioritize needs: must-have, preferred and optional. Clarify timing, decision participants and whether the customer has a trade. Ask whether they plan to pay cash or explore financing, and whether a responsible monthly range matters. Summarize what you heard and ask permission to select the best-fit unit."}, {"heading": "Self-Coaching", "body": "Watch for asking a checklist of questions without listening; use follow-up questions connected to the customer''s last answer. Watch for avoiding financing questions because the customer may be offended; explain the purpose and offer options without assuming. Watch for skipping decision participants; clarify who will use the unit and who must be comfortable with the decision. Watch for showing inventory before summarizing; repeat the priorities and earn agreement before selecting."}], "wordTracks": [{"label": "Set the agenda", "text": "Before we start walking inventory, may I ask a few questions so I don''t waste your time showing you the wrong things?"}, {"label": "Primary use", "text": "Tell me how you expect to use it most often."}, {"label": "Current unit", "text": "What are you using now, and what would you like the next one to do better?"}, {"label": "Priorities", "text": "Of everything you mentioned, which two or three items are non-negotiable?"}, {"label": "Decision process", "text": "Who else will use it or be involved in the decision?"}, {"label": "Purchase structure", "text": "Are you planning to pay cash, use outside financing or would you like us to compare options for you?"}, {"label": "Summary", "text": "Let me make sure I have this right..."}, {"label": "Advance", "text": "Based on what you shared, I have a strong first choice in mind. Let me verify it and bring my manager into the process."}], "practice": [{"title": "Practice Lab: Discovery Without Interrogation", "instructions": "The customer says they want \"something affordable\" for weekend use but provides limited detail. The salesperson must uncover use, users, must-haves, trade, timing and purchase structure. Success standard: at least five useful facts are uncovered, the salesperson summarizes accurately, the customer agrees with the summary and no unit is selected until discovery is complete."}], "commitment": "On my next customer, I will apply this specific behavior."}'::jsonb, '{"number": 2, "managerCheckpoints": ["Review whether CRM notes contain useful discovery, not just looking for side-by-side", "Ask the salesperson to state the customer''s top three priorities before approving unit selection", "Coach missing questions one at a time instead of demanding a longer interrogation"], "coachingNotes": ["Use follow-up questions connected to the customer''s last answer instead of asking a checklist of questions without listening", "Explain the purpose of financing questions and offer options without assuming the customer will be offended", "Clarify who will use the unit and who must be comfortable with the decision", "Repeat the priorities and earn agreement before selecting. Never show inventory before summarizing", "Good discovery is a conversation with direction. Ask, listen, clarify and summarize", "Do not ask for information that has no purpose. Explain why sensitive questions matter"], "roleplayLabs": [{"title": "Discovery Without Interrogation", "scenario": "The customer says they want something affordable for weekend use but provides limited detail. The salesperson must uncover use, users, must-haves, trade, timing and purchase structure. Roles: salesperson, customer with hidden priorities and observer tracking open and closed questions.", "evaluationCriteria": ["At least five useful facts are uncovered", "Salesperson summarizes accurately", "Customer agrees with the summary", "No unit is selected until discovery is complete"]}], "signoffCriteria": ["Conducts a conversational needs assessment", "Captures useful notes without making the customer feel interrogated", "Identifies use, users, priorities, trade, timing and purchase structure", "Summarizes the discovery and earns permission to select a unit"]}'::jsonb)
on conflict (number) do update set
  slug = excluded.slug,
  title = excluded.title,
  purpose = excluded.purpose,
  content = excluded.content,
  manager_content = excluded.manager_content,
  version = public.steps.version + 1,
  updated_at = now();

delete from public.knowledge_check_questions
  where step_id = (select id from public.steps where number = 2);

insert into public.knowledge_check_questions (step_id, position, question, options, answer_index)
values ((select id from public.steps where number = 2), 0, 'Why is a summary essential before selecting a unit?', '["It gives the manager time to prepare numbers", "It repeats the priorities and earns the customer''s agreement before showing inventory", "It proves the salesperson took good notes", "It is required for CRM documentation"]'::jsonb, 1);

insert into public.knowledge_check_questions (step_id, position, question, options, answer_index)
values ((select id from public.steps where number = 2), 1, 'Which set best names the core discovery categories?', '["Credit score, income, employment and residence", "Color preference, brand loyalty, hobbies and budget", "Use, users, priorities, trade, timing and purchase structure", "Price, payment, term and rate"]'::jsonb, 2);

insert into public.knowledge_check_questions (step_id, position, question, options, answer_index)
values ((select id from public.steps where number = 2), 2, 'How do you ask about financing without assuming the answer?', '["Ask whether they plan to pay cash, use outside financing or would like you to compare options", "Wait for the business manager to bring it up", "Ask what monthly payment they can afford", "Assume financing unless the customer objects"]'::jsonb, 0);

insert into public.knowledge_check_questions (step_id, position, question, options, answer_index)
values ((select id from public.steps where number = 2), 3, 'What should you do instead of asking a checklist of questions without listening?', '["Shorten the interview to two questions", "Let the customer fill out a form instead", "Skip discovery and rely on the walkaround", "Use follow-up questions connected to the customer''s last answer"]'::jsonb, 3);


-- Step 3: Select a Unit & Manager Introduction
insert into public.steps (number, slug, title, purpose, content, manager_content)
values (3, 'select-a-unit-and-manager-introduction', 'Select a Unit & Manager Introduction', 'Use the discovery to narrow the choice, build confidence and connect the customer with dealership leadership early.', '{"purpose": "Use the discovery to narrow the choice, build confidence and connect the customer with dealership leadership early.", "learn": [{"heading": "What Success Looks Like", "body": "Select a first-choice unit based on stated priorities. Use a purposeful desk touch and manager introduction. Explain the manager''s value without weakening the salesperson. Prepare a credible Plan B without overwhelming the customer."}, {"heading": "Execution Checklist", "body": "Review the discovery and identify the best-fit unit plus one Plan B. Touch the desk before leaving for inventory. Brief the manager on the customer, use and priorities. Introduce the manager by name and role. The manager welcomes the customer and reinforces the salesperson. Confirm availability, key equipment and any dealership-specific information. Bring the unit to a presentation area when practical. Separate it from the row and prepare it for presentation. Explain why it is the first choice using the customer''s own priorities. Use Plan B only when the first choice misses a required need or the customer identifies a meaningful concern."}, {"heading": "Self-Coaching", "body": "Watch for selecting the unit before discovery; require the salesperson to explain the match in the customer''s words. Watch for introducing the manager only when there is a problem; make the introduction early and routine. Watch for the manager taking over and sidelining the salesperson; the manager strengthens the salesperson, then returns ownership. Watch for showing three or four units at once; begin with one deliberate choice and add a second only for a reason."}], "wordTracks": [{"label": "Desk touch", "text": "Based on what you shared, I have a strong first choice. I''m going to verify it with my manager and make sure we have the right information before we walk out."}, {"label": "Manager introduction", "text": "[Customer], this is [Manager], our [Role]. I''ll be checking with [him/her/them] throughout your visit so we can answer everything accurately."}, {"label": "Manager reinforcement", "text": "You''re in good hands with [Salesperson]. [They] know our process and will help you compare this correctly. I''ll stay involved as needed."}, {"label": "Unit reveal", "text": "I selected this one first because it gives you [priority one], [priority two] and the [specific capability] you said mattered most."}, {"label": "Plan B", "text": "I also have a second option in mind, but let''s evaluate this one against your priorities before we add another choice."}], "practice": [{"title": "Practice Lab: The First Choice", "instructions": "Using a completed discovery worksheet, the salesperson briefs the manager, introduces the manager and presents one first-choice unit. Success standard: the manager receives a concise customer brief, the introduction adds confidence, the unit selection is tied to priorities and Plan B is mentioned without creating confusion."}], "commitment": "On my next customer, I will apply this specific behavior."}'::jsonb, '{"number": 3, "managerCheckpoints": ["Require a concise customer brief before the salesperson leaves the desk", "Use the introduction to learn the customer''s name and confirm one priority", "Track manager contacts and unsold customers who left without a manager conversation"], "coachingNotes": ["Require the salesperson to explain the unit match in the customer''s words. Never select the unit before discovery", "Make the manager introduction early and routine, not a rescue after the salesperson has lost control", "The manager strengthens the salesperson, then returns ownership. The manager must not take over and sideline the salesperson", "Begin with one deliberate choice and add a second only for a reason. Too many choices create confusion", "No customer should leave without manager contact when dealership policy requires it"], "roleplayLabs": [{"title": "The First Choice", "scenario": "Using a completed discovery worksheet, the salesperson briefs the manager, introduces the manager and presents one first-choice unit. Roles: salesperson, manager, customer and observer.", "evaluationCriteria": ["Manager receives a concise customer brief", "Introduction adds confidence", "Unit selection is tied to priorities", "Plan B is mentioned without creating confusion"]}], "signoffCriteria": ["Selects a first-choice unit based on stated priorities", "Uses a purposeful desk touch and manager introduction", "Explains the manager''s value without weakening the salesperson", "Prepares a credible Plan B without overwhelming the customer"]}'::jsonb)
on conflict (number) do update set
  slug = excluded.slug,
  title = excluded.title,
  purpose = excluded.purpose,
  content = excluded.content,
  manager_content = excluded.manager_content,
  version = public.steps.version + 1,
  updated_at = now();

delete from public.knowledge_check_questions
  where step_id = (select id from public.steps where number = 3);

insert into public.knowledge_check_questions (step_id, position, question, options, answer_index)
values ((select id from public.steps where number = 3), 0, 'Why should the manager introduction happen early?', '["So the manager can start working numbers immediately", "So the salesperson can take a break during the visit", "It makes the introduction routine and adds confidence instead of signaling a problem", "It is only required for appointment customers"]'::jsonb, 2);

insert into public.knowledge_check_questions (step_id, position, question, options, answer_index)
values ((select id from public.steps where number = 3), 1, 'What information belongs in the manager brief at the desk touch?', '["The customer''s credit history and income", "The customer, their use and their priorities", "The discount the salesperson plans to offer", "Only the stock number of the selected unit"]'::jsonb, 1);

insert into public.knowledge_check_questions (step_id, position, question, options, answer_index)
values ((select id from public.steps where number = 3), 2, 'When should Plan B be introduced?', '["At the same time as the first choice so the customer can compare", "Whenever the customer hesitates on anything", "Before discovery so options stay open", "Only when the first choice misses a required need or the customer identifies a meaningful concern"]'::jsonb, 3);

insert into public.knowledge_check_questions (step_id, position, question, options, answer_index)
values ((select id from public.steps where number = 3), 3, 'What should the manager do during the introduction?', '["Welcome the customer, reinforce the salesperson and then return ownership", "Take over the presentation from the salesperson", "Present the numbers while momentum is high", "Stay at the desk unless a problem develops"]'::jsonb, 0);


-- Step 4: Feature Function & Benefit Presentation
insert into public.steps (number, slug, title, purpose, content, manager_content)
values (4, 'feature-function-and-benefit-presentation', 'Feature Function & Benefit Presentation', 'Translate product knowledge into personal value the customer can see, feel and remember.', '{"purpose": "Translate product knowledge into personal value the customer can see, feel and remember.", "learn": [{"heading": "What Success Looks Like", "body": "Explain the difference between a feature, function and benefit. Build a presentation around discovery instead of reciting every specification. Use an organized walkaround that fits the product category. Confirm value with customer participation and questions."}, {"heading": "Execution Checklist", "body": "Restate the customer''s top priorities before beginning. Use a consistent presentation route: exterior/front, operator area, passenger or cargo area, rear/service access and final seating position. For each important item, name the feature, explain its function and connect the benefit to the customer''s use. Use evidence: demonstrate, show a label, compare capacity or explain the design accurately. Invite the customer to interact with the unit and ask a check-in question. Avoid unsupported claims and verify uncertain information. End by summarizing the three strongest reasons this unit fits."}, {"heading": "Self-Coaching", "body": "Watch for reciting the brochure; limit the presentation to relevant priorities and value-building support. Watch for naming features without benefits; require every major feature to end with \"which means...\" Watch for making claims the salesperson cannot support; verify the fact and explain the source. Watch for talking continuously; create customer interaction and check-in questions."}], "wordTracks": [{"label": "Connect to discovery", "text": "You said [priority] mattered because [reason]. This feature is designed specifically for that."}, {"label": "FFB", "text": "This has [feature]. It [function], which means you get [personal benefit]."}, {"label": "Customer participation", "text": "Go ahead and try that. What do you notice?"}, {"label": "Check-in", "text": "How does that compare with what you are using now?"}, {"label": "Verify information", "text": "I want to make sure I give you the exact specification. Let me verify that rather than guess."}, {"label": "Summary", "text": "The three strongest matches for you are [one], [two] and [three]."}], "practice": [{"title": "Practice Lab: Turn Specifications into Value", "instructions": "The trainer assigns a product feature and a customer use. The salesperson must deliver three different FFB explanations for three different customer profiles. Success standard: the feature is accurate, the function is clear, the benefit is personal and specific and the customer is invited to interact or respond."}], "commitment": "On my next customer, I will apply this specific behavior."}'::jsonb, '{"number": 4, "managerCheckpoints": ["Use daily walkarounds to assign one FFB to each salesperson", "Ask why does that matter to this customer whenever a salesperson recites a specification", "Correct inaccurate product claims immediately"], "coachingNotes": ["Limit the presentation to relevant priorities and value-building support instead of reciting the brochure", "Require every major feature to end with which means so the benefit is stated", "Verify the fact and explain the source rather than making claims the salesperson cannot support", "Create customer interaction and check-in questions instead of talking continuously", "Involve the customer. Opening, touching, sitting, loading, connecting and comparing create ownership", "End by summarizing the three strongest reasons this unit fits"], "roleplayLabs": [{"title": "Turn Specifications into Value", "scenario": "The trainer assigns a product feature and a customer use. The salesperson must deliver three different FFB explanations for three different customer profiles. Roles: salesperson, customer profile reader and observer.", "evaluationCriteria": ["Feature is accurate", "Function is clear", "Benefit is personal and specific", "Customer is invited to interact or respond"]}], "signoffCriteria": ["Explains the difference between a feature, function and benefit", "Builds a presentation around discovery instead of reciting every specification", "Uses an organized walkaround that fits the product category", "Confirms value with customer participation and questions"]}'::jsonb)
on conflict (number) do update set
  slug = excluded.slug,
  title = excluded.title,
  purpose = excluded.purpose,
  content = excluded.content,
  manager_content = excluded.manager_content,
  version = public.steps.version + 1,
  updated_at = now();

delete from public.knowledge_check_questions
  where step_id = (select id from public.steps where number = 4);

insert into public.knowledge_check_questions (step_id, position, question, options, answer_index)
values ((select id from public.steps where number = 4), 0, 'Which statement correctly defines feature, function and benefit?', '["A feature is the price, the function is the payment and the benefit is the savings", "A feature is what the unit has, the function is what it does and the benefit is what that means personally for the customer", "A feature is the warranty, the function is the coverage and the benefit is the term", "Feature, function and benefit are three names for the same thing"]'::jsonb, 1);

insert into public.knowledge_check_questions (step_id, position, question, options, answer_index)
values ((select id from public.steps where number = 4), 1, 'Why should the presentation route be consistent?', '["An organized walkaround that fits the product category keeps the presentation complete and professional", "It allows the salesperson to memorize one script for every customer", "It guarantees the customer will buy", "It helps the salesperson finish faster and take more customers"]'::jsonb, 0);

insert into public.knowledge_check_questions (step_id, position, question, options, answer_index)
values ((select id from public.steps where number = 4), 2, 'What question turns a product monologue into customer participation?', '["Do you want to hear about the warranty next?", "Can I show you one more thing?", "Go ahead and try that. What do you notice?", "Are you ready to talk numbers?"]'::jsonb, 2);

insert into public.knowledge_check_questions (step_id, position, question, options, answer_index)
values ((select id from public.steps where number = 4), 3, 'How should the presentation end?', '["With a full recital of the remaining specifications", "With a direct request for a deposit", "With the brochure and a business card", "By summarizing the three strongest reasons this unit fits"]'::jsonb, 3);


-- Step 5: Demonstration Drive
insert into public.steps (number, slug, title, purpose, content, manager_content)
values (5, 'demonstration-drive', 'Demonstration Drive', 'Let the customer experience the product safely while reinforcing the value that matters most.', '{"purpose": "Let the customer experience the product safely while reinforcing the value that matters most.", "learn": [{"heading": "What Success Looks Like", "body": "Prepare and lead a safe, purposeful demonstration. Use the route to reinforce selected benefits. Transfer control to the customer according to dealership policy. Create emotional ownership and gather buying signals."}, {"heading": "Execution Checklist", "body": "Confirm the unit is safe, fueled or charged, clean and ready. Complete required license, insurance, waiver and protective-equipment steps. Explain controls, route, expectations and safety before moving. When policy supports it, the salesperson demonstrates first and narrates only the most relevant functions. Transfer control safely and let the customer experience the product without constant talking. Ask ownership and trial-close questions at natural points. Return to a designated area, confirm the fit and transition into the Trial Close."}, {"heading": "Self-Coaching", "body": "Watch for improvising an unsafe route; use an approved route and product-specific safety policy. Watch for talking through the entire customer drive; allow quiet experience, then ask focused questions. Watch for using extreme capability demonstrations; demonstrate responsibly and within dealership/manufacturer guidance. Watch for returning without confirming fit; ask an ownership question and transition directly to the Trial Close."}], "wordTracks": [{"label": "Pre-drive", "text": "Before we move, I''ll review the controls, our route and the safety items so you know exactly what to expect."}, {"label": "Demonstrate", "text": "Watch what happens when I use [feature]. This is where it helps with [customer use]."}, {"label": "Customer drive", "text": "I''ll switch with you here. Take a moment to adjust everything before we move."}, {"label": "Ownership question", "text": "Where do you picture using this first?"}, {"label": "Buying signal", "text": "What has impressed you most so far?"}, {"label": "Return", "text": "Let''s park it in our delivery area and make sure it checks every box before we review the next step."}], "practice": [{"title": "Practice Lab: Purposeful Demo", "instructions": "The salesperson must conduct a pre-drive briefing, demonstrate one relevant function, transfer control and ask two ownership questions. Success standard: safety steps are complete, narration is relevant, the customer receives time to experience and buying signals are captured."}], "commitment": "On my next customer, I will apply this specific behavior."}'::jsonb, '{"number": 5, "managerCheckpoints": ["Approve routes and verify policy compliance", "Observe whether demos actually occur or are replaced with parking-lot conversations", "Review one buying signal with the salesperson before numbers are presented"], "coachingNotes": ["Use an approved route and product-specific safety policy. Never improvise an unsafe route", "Allow quiet experience, then ask focused questions instead of talking through the entire customer drive", "Demonstrate responsibly and within dealership and manufacturer guidance. No extreme capability demonstrations", "Ask an ownership question and transition directly to the Trial Close instead of returning without confirming fit", "Safety, licensing, waivers, protective equipment and dealership policy are never optional", "A presentation tells. A demonstration proves"], "roleplayLabs": [{"title": "Purposeful Demo", "scenario": "The salesperson must conduct a pre-drive briefing, demonstrate one relevant function, transfer control and ask two ownership questions. Roles: salesperson, customer, safety observer and value observer.", "evaluationCriteria": ["Safety steps are complete", "Narration is relevant", "Customer receives time to experience", "Buying signals are captured"]}], "signoffCriteria": ["Prepares and leads a safe, purposeful demonstration", "Uses the route to reinforce selected benefits", "Transfers control to the customer according to dealership policy", "Creates emotional ownership and gathers buying signals"]}'::jsonb)
on conflict (number) do update set
  slug = excluded.slug,
  title = excluded.title,
  purpose = excluded.purpose,
  content = excluded.content,
  manager_content = excluded.manager_content,
  version = public.steps.version + 1,
  updated_at = now();

delete from public.knowledge_check_questions
  where step_id = (select id from public.steps where number = 5);

insert into public.knowledge_check_questions (step_id, position, question, options, answer_index)
values ((select id from public.steps where number = 5), 0, 'What must be completed before the unit moves?', '["The trade appraisal and payoff verification", "Required license, insurance, waiver and protective-equipment steps plus a review of controls, route and safety", "A signed purchase agreement", "The manager''s approval of the numbers"]'::jsonb, 1);

insert into public.knowledge_check_questions (step_id, position, question, options, answer_index)
values ((select id from public.steps where number = 5), 1, 'Why should the demonstration route be purposeful?', '["It uses the route to reinforce selected benefits while staying safe and approved", "It keeps the drive as short as possible", "It shows off the unit''s maximum capability", "It avoids traffic so the customer relaxes"]'::jsonb, 0);

insert into public.knowledge_check_questions (step_id, position, question, options, answer_index)
values ((select id from public.steps where number = 5), 2, 'What should the salesperson do after the customer has experienced the product?', '["Head straight to the finance office", "Start the trade walkaround immediately", "Return to a designated area, confirm the fit and transition into the Trial Close", "Offer a second demonstration on a different unit"]'::jsonb, 2);

insert into public.knowledge_check_questions (step_id, position, question, options, answer_index)
values ((select id from public.steps where number = 5), 3, 'How should the salesperson behave while the customer is driving?', '["Narrate every feature continuously to build value", "Discuss numbers to save time", "Stay silent for the entire drive no matter what", "Allow quiet experience, then ask focused ownership questions at natural points"]'::jsonb, 3);


-- Step 6: Trial Close
insert into public.steps (number, slug, title, purpose, content, manager_content)
values (6, 'trial-close', 'Trial Close', 'Measure readiness, uncover hesitation and earn small commitments before presenting numbers.', '{"purpose": "Measure readiness, uncover hesitation and earn small commitments before presenting numbers.", "learn": [{"heading": "What Success Looks Like", "body": "Recognize natural moments for a trial close. Use low-pressure questions that measure ownership and fit. Respond productively to a negative or uncertain answer. Avoid treating a trial close as the final close."}, {"heading": "Execution Checklist", "body": "Listen for buying signals: delivery questions, accessory questions, ownership language, approval from a partner or concern about one remaining issue. Ask a simple fit, preference or conditional-commitment question. If the answer is positive, reinforce and advance. If the answer is uncertain, ask what would need to change. If the answer is negative, isolate whether the issue is product, timing, trade, price, payment or another decision participant. Resolve or select a better unit before presenting numbers."}, {"heading": "Self-Coaching", "body": "Watch for asking a trial close before building value; earn the question with discovery and demonstration first. Watch for using manipulative tag questions repeatedly; ask direct, natural questions and listen to the answer. Watch for ignoring a negative answer; clarify the concern before advancing. Watch for never asking for any commitment until the final close; use small commitments to prevent surprises later."}], "wordTracks": [{"label": "Fit", "text": "Is this the unit you would most like to own?"}, {"label": "Conditional", "text": "If the numbers fit the responsible range we discussed, are you comfortable moving forward with this one?"}, {"label": "Preference", "text": "Which do you prefer: the [option A] or [option B]?"}, {"label": "Ownership", "text": "What do you think your family or team will like most about this?"}, {"label": "Uncertain answer", "text": "What is the one thing keeping it from feeling like the right fit?"}, {"label": "Advance", "text": "Good. Let''s introduce you to service and parts, then we''ll review your trade and the numbers."}], "practice": [{"title": "Practice Lab: The Honest Temperature Check", "instructions": "The customer likes the unit but says, \"I''m not sure yet.\" The salesperson must use a trial close, clarify the concern and choose the correct next step. Success standard: the question is natural and specific, the salesperson listens to the answer, the concern is categorized correctly and the next step fits the concern."}], "commitment": "On my next customer, I will apply this specific behavior."}'::jsonb, '{"number": 6, "managerCheckpoints": ["Ask the salesperson to report the customer''s trial-close response before presenting numbers", "Coach the difference between a buying signal and an assumption", "Do not permit numbers to become the first serious commitment conversation"], "coachingNotes": ["Earn the trial close with discovery and demonstration first. Never ask before building value", "Ask direct, natural questions and listen to the answer instead of using manipulative tag questions repeatedly", "Clarify the concern before advancing. Never ignore a negative answer", "Use small commitments to prevent surprises later instead of waiting for the final close", "A trial close is a temperature check. It does not replace the final ask", "A hesitant answer is useful information. Clarify the concern instead of arguing"], "roleplayLabs": [{"title": "The Honest Temperature Check", "scenario": "The customer likes the unit but says I''m not sure yet. The salesperson must use a trial close, clarify the concern and choose the correct next step. Roles: salesperson, customer and observer.", "evaluationCriteria": ["Question is natural and specific", "Salesperson listens to the answer", "Concern is categorized correctly", "Next step fits the concern"]}], "signoffCriteria": ["Recognizes natural moments for a trial close", "Uses low-pressure questions that measure ownership and fit", "Responds productively to a negative or uncertain answer", "Avoids treating a trial close as the final close"]}'::jsonb)
