values ((select id from public.steps where number = 6), 0, 'What is the purpose of a trial close?', '["To measure readiness, uncover hesitation and earn small commitments before presenting numbers", "To force a final decision before the customer leaves", "To replace the demonstration drive", "To get the customer to sign paperwork immediately"]'::jsonb, 0);

insert into public.knowledge_check_questions (step_id, position, question, options, answer_index)
values ((select id from public.steps where number = 6), 1, 'What should happen after a negative response to a trial close?', '["Move straight to numbers to change the momentum", "End the visit and schedule a follow-up call", "Isolate whether the issue is product, timing, trade, price, payment or another decision participant", "Repeat the same question with different words"]'::jsonb, 2);

insert into public.knowledge_check_questions (step_id, position, question, options, answer_index)
values ((select id from public.steps where number = 6), 2, 'Which of the following are buying signals that create a natural trial-close moment?', '["Checking the time, yawning and stepping away", "Delivery questions, accessory questions and ownership language", "Asking for a business card at the door", "Silence during the walkaround"]'::jsonb, 1);

insert into public.knowledge_check_questions (step_id, position, question, options, answer_index)
values ((select id from public.steps where number = 6), 3, 'When has the salesperson earned the right to ask a trial close?', '["As soon as the customer picks a unit off the row", "Only after numbers have been presented", "During the initial greeting", "After building value through discovery and demonstration"]'::jsonb, 3);


-- Step 7: Service & Parts Tour Introduction
insert into public.steps (number, slug, title, purpose, content, manager_content)
values (7, 'service-and-parts-tour-introduction', 'Service & Parts Tour Introduction', 'Show the customer how the dealership supports ownership after the sale and strengthen the reason to buy here.', '{"purpose": "Show the customer how the dealership supports ownership after the sale and strengthen the reason to buy here.", "learn": [{"heading": "What Success Looks Like", "body": "Explain why service and parts belong before finance. Deliver a concise tour or introduction without creating delay. Edify dealership teammates and ownership resources. Connect retention benefits to the customer''s intended use."}, {"heading": "Execution Checklist", "body": "Preview the purpose: explain that you want to show another reason customers choose the dealership. Walk the customer to service and parts or bring the appropriate teammate to the customer when distance or timing requires. Introduce the advisor or manager by name and role. Edify the employee with one credible reason they are valuable. Highlight scheduling, maintenance, parts availability, accessories, warranty support, pickup/delivery or other approved services. Connect one service or parts capability to the customer''s use. Return smoothly to trade and numbers without allowing the interaction to stall."}, {"heading": "Self-Coaching", "body": "Watch for skipping the step because the store is busy; use a brief prepared introduction or alternate approved method. Watch for turning the tour into a long department presentation; focus on two or three ownership benefits. Watch for offering services the dealership does not provide; use only verified capabilities. Watch for introducing the customer without context; share the customer''s use and likely ownership need."}], "wordTracks": [{"label": "Transition", "text": "Before we review the numbers, I want to show you another reason customers choose to own through us."}, {"label": "Introduction", "text": "[Customer], this is [Name], one of our [service advisors/parts specialists]. [Name] is especially good at helping owners with [specific strength]."}, {"label": "Edify customer", "text": "[Name], [Customer] plans to use the unit for [use], so [service/accessory need] will be important."}, {"label": "Ownership value", "text": "This gives you a direct contact after the sale instead of sending you to a generic call center."}, {"label": "Return", "text": "Thank you, [Name]. [Customer], let''s take a look at your trade and put the complete picture together."}], "practice": [{"title": "Practice Lab: Why Buy Here?", "instructions": "The salesperson has two minutes to introduce service and parts and connect one capability to the customer''s stated use. Success standard: the purpose is explained, the teammate is introduced by name, one relevant ownership benefit is connected and the transition back to the process is smooth."}], "commitment": "On my next customer, I will apply this specific behavior."}'::jsonb, '{"number": 7, "managerCheckpoints": ["Coordinate with service and parts so the step is expected and supported", "Observe whether salespeople edify accurately or use vague praise", "Track skipped tours and the reason they were skipped"], "coachingNotes": ["Use a brief prepared introduction or alternate approved method instead of skipping the step because the store is busy", "Focus on two or three ownership benefits instead of turning the tour into a long department presentation", "Use only verified capabilities. Never offer services the dealership does not provide", "Share the customer''s use and likely ownership need instead of introducing the customer without context", "Edification must be genuine and specific. False praise feels scripted", "The introduction should be brief, prepared and relevant to ownership"], "roleplayLabs": [{"title": "Why Buy Here?", "scenario": "The salesperson has two minutes to introduce service and parts and connect one capability to the customer''s stated use. Roles: salesperson, service or parts teammate, customer and observer.", "evaluationCriteria": ["Purpose is explained", "Teammate is introduced by name", "One relevant ownership benefit is connected", "Transition back to the process is smooth"]}], "signoffCriteria": ["Explains why service and parts belong before finance", "Delivers a concise tour or introduction without creating delay", "Edifies dealership teammates and ownership resources", "Connects retention benefits to the customer''s intended use"]}'::jsonb)
