values ((select id from public.steps where number = 7), 0, 'Why does the Service & Parts Tour occur before finance?', '["Because the finance office is usually busy at that point", "It shows how the dealership supports ownership after the sale and strengthens the reason to buy here before numbers are finalized", "So the service department can inspect the trade", "It gives the manager time to prepare paperwork"]'::jsonb, 1);

insert into public.knowledge_check_questions (step_id, position, question, options, answer_index)
values ((select id from public.steps where number = 7), 1, 'What makes edification of a teammate credible?', '["Calling them the best in the state", "Listing every service the department offers", "One credible, specific reason they are valuable to owners", "Mentioning how long they have worked there"]'::jsonb, 2);

insert into public.knowledge_check_questions (step_id, position, question, options, answer_index)
values ((select id from public.steps where number = 7), 2, 'How long should the service and parts introduction take?', '["It should be concise, about two minutes, without creating delay", "As long as the customer keeps asking questions", "At least fifteen minutes to build full value", "It should be skipped when the store is busy"]'::jsonb, 0);

insert into public.knowledge_check_questions (step_id, position, question, options, answer_index)
values ((select id from public.steps where number = 7), 3, 'What should the salesperson share when introducing the customer to a service or parts teammate?', '["The negotiated price of the unit", "The customer''s credit situation", "Nothing, the introduction should stay generic", "The customer''s use and likely ownership need"]'::jsonb, 3);


-- Step 8: Trade Appraisal & Assessment
insert into public.steps (number, slug, title, purpose, content, manager_content)
values (8, 'trade-appraisal-and-assessment', 'Trade Appraisal & Assessment', 'Collect accurate information, involve the customer and protect trust while the dealership determines market value.', '{"purpose": "Collect accurate information, involve the customer and protect trust while the dealership determines market value.", "learn": [{"heading": "What Success Looks Like", "body": "Separate payoff from market value. Conduct a professional walkaround and condition review. Capture complete trade information in the approved system. Use neutral language and avoid devaluing games."}, {"heading": "Execution Checklist", "body": "Ask the customer to tell you what they like about the trade and what a future buyer should know. Enter year, make, model, identification number, mileage/hours, equipment and ownership information in the CRM or appraisal tool. Ask whether there is a payoff and identify the lender; explain that payoff does not determine market value. Walk around the trade with the customer. Note visible damage, wear, accessories, tires, keys, records and missing items. Ask the customer what they would address first if selling it to a close friend. Collect photos and required documentation according to dealership policy. Present the complete information to the appraiser or manager without promising a value."}, {"heading": "Self-Coaching", "body": "Watch for promising a value before the appraisal; set the expectation that the appraiser determines the supported value. Watch for using payoff as proof of value; explain equity or negative equity only after both facts are known. Watch for criticizing the customer''s trade; document condition neutrally and respectfully. Watch for completing the appraisal without customer involvement; use the walkaround to gather information and reduce surprises."}], "wordTracks": [{"label": "Invite ownership story", "text": "Tell me what you have liked most about this unit and anything a future owner should know."}, {"label": "Payoff", "text": "Is it paid for, or is there a lender we will need to contact for an exact payoff?"}, {"label": "Separate value", "text": "The payoff and market value are separate. We''ll calculate both so you can see the complete position clearly."}, {"label": "Condition", "text": "Let''s walk it together so we record the equipment and condition accurately."}, {"label": "Customer insight", "text": "If you were selling it to a close friend, what is the first thing you would tell them to address?"}, {"label": "No promise", "text": "I''ll provide the full information to our appraiser and bring you the value we can support in today''s market."}], "practice": [{"title": "Practice Lab: Trade Without Tension", "instructions": "The customer owes more than they expect the trade to be worth and says, \"I need payoff.\" The salesperson must separate payoff, value and structure without arguing. Success standard: payoff and value are explained separately, condition language remains neutral, no unsupported value is promised and the customer understands the next step."}], "commitment": "On my next customer, I will apply this specific behavior."}'::jsonb, '{"number": 8, "managerCheckpoints": ["Inspect appraisal completeness before assigning value", "Coach neutral condition language and stop beat up the trade tactics", "Explain the market evidence behind the appraisal when appropriate"], "coachingNotes": ["Set the expectation that the appraiser determines the supported value. Never promise a value before the appraisal", "Explain equity or negative equity only after both facts are known. Payoff is not proof of value", "Document condition neutrally and respectfully. Never criticize the customer''s trade", "Use the walkaround with the customer to gather information and reduce surprises", "The salesperson gathers facts; the approved manager or appraisal process determines value", "Condition should be documented objectively, not dramatized to create fear"], "roleplayLabs": [{"title": "Trade Without Tension", "scenario": "The customer owes more than they expect the trade to be worth and says I need payoff. The salesperson must separate payoff, value and structure without arguing. Roles: salesperson, customer and appraisal observer.", "evaluationCriteria": ["Payoff and value are explained separately", "Condition language remains neutral", "No unsupported value is promised", "Customer understands the next step"]}], "signoffCriteria": ["Separates payoff from market value", "Conducts a professional walkaround and condition review with the customer", "Captures complete trade information in the approved system", "Uses neutral language and avoids devaluing games"]}'::jsonb)
