values ((select id from public.steps where number = 8), 0, 'Who determines the trade value?', '["The salesperson based on online guides", "The customer based on their payoff", "The appraiser or manager based on current market and condition", "The lender that holds the loan"]'::jsonb, 2);

insert into public.knowledge_check_questions (step_id, position, question, options, answer_index)
values ((select id from public.steps where number = 8), 1, 'How do payoff and market value differ?', '["Payoff is what is owed to the lender while market value is what the dealership can support; they are separate figures", "They are the same number when the loan is current", "Payoff is always lower than market value", "Market value is set by the lender and payoff is set by the appraiser"]'::jsonb, 0);

insert into public.knowledge_check_questions (step_id, position, question, options, answer_index)
values ((select id from public.steps where number = 8), 2, 'Why should the customer participate in the condition walkaround?', '["So the customer can negotiate the value on the spot", "It is required by law in most states", "So the salesperson can point out every flaw to lower the value", "It gathers accurate information and reduces surprises later"]'::jsonb, 3);

insert into public.knowledge_check_questions (step_id, position, question, options, answer_index)
values ((select id from public.steps where number = 8), 3, 'What should the salesperson promise about the trade value during the walkaround?', '["A range based on similar units on the lot", "No value; provide the full information to the appraiser and bring back the value the dealership can support", "At least the payoff amount", "The average of the major online guides"]'::jsonb, 1);


-- Step 9: Present Numbers
insert into public.steps (number, slug, title, purpose, content, manager_content)
values (9, 'present-numbers', 'Present Numbers', 'Present the complete proposal clearly, confidently and in the value context already established.', '{"purpose": "Present the complete proposal clearly, confidently and in the value context already established.", "learn": [{"heading": "What Success Looks Like", "body": "Prepare before presenting the proposal. Use consistent terminology and presentation order. Explain price, trade, cash investment and payment options accurately. Ask for a clear commitment and return to the manager with useful information."}, {"heading": "Execution Checklist", "body": "Before returning, review the proposal with the manager and understand every figure. Reconnect to the customer''s selected unit and top reasons for choosing it. Present the selling price and approved disclosures. Present the trade value, payoff and equity position separately. Present approved cash-investment and payment choices or explain the next finance step, depending on dealership process. Use a pen or visual guide to control the presentation without hiding information. Ask which option works best or ask directly for authorization to proceed. When the customer resists, listen, clarify the reason and return to the manager with a commitment or specific concern."}, {"heading": "Self-Coaching", "body": "Watch for apologizing for the numbers before presenting them; present calmly and let the customer respond. Watch for talking continuously after asking for commitment; pause and give the customer time to process. Watch for changing figures without manager approval; return with the exact concern and commitment. Watch for focusing only on payment; keep price, trade, cash investment and payment structure clear and separate."}], "wordTracks": [{"label": "Reconnect value", "text": "You selected this unit because it gives you [priority one], [priority two] and [priority three]. Here is the complete proposal."}, {"label": "Price", "text": "The approved selling price is [amount], with the required fees and taxes shown separately here."}, {"label": "Trade", "text": "Your trade value is [amount]. The verified payoff is [amount], which creates [equity/negative equity] of [amount]."}, {"label": "Options", "text": "Here are the approved structures. Which one is closest to the responsible range you had in mind?"}, {"label": "Direct ask", "text": "If this works for you, authorize it here and we''ll move to the next step."}, {"label": "Clarify resistance", "text": "Help me understand what part is not working: the unit, the overall price, the trade position, the cash investment or the monthly structure?"}, {"label": "Return to manager", "text": "If we can resolve [specific issue], are you prepared to move forward today?"}], "practice": [{"title": "Practice Lab: Clear Proposal, Clear Ask", "instructions": "The customer likes the unit but reacts to the monthly option. The salesperson must identify whether the issue is payment, cash investment, term, trade or overall value. Success standard: the proposal is explained in order, figures are not improvised, the salesperson pauses after the ask and the concern is isolated before returning to the manager."}], "commitment": "On my next customer, I will apply this specific behavior."}'::jsonb, '{"number": 9, "managerCheckpoints": ["Review the pencil with the salesperson before presentation", "Require a specific objection and conditional commitment on every return", "Coach payment-only presentations and unclear trade and equity explanations"], "coachingNotes": ["Present calmly and let the customer respond. Never apologize for the numbers before presenting them", "Pause after asking for commitment. Give the customer time to process", "Return with the exact concern and commitment. Never change figures without manager approval", "Keep price, trade, cash investment and payment structure clear and separate instead of focusing only on payment", "Numbers should not be the first time the customer experiences value or commitment", "Present the approved proposal exactly as structured. Do not improvise discounts, rates or payments"], "roleplayLabs": [{"title": "Clear Proposal, Clear Ask", "scenario": "The customer likes the unit but reacts to the monthly option. The salesperson must identify whether the issue is payment, cash investment, term, trade or overall value. Roles: salesperson, customer and manager observer.", "evaluationCriteria": ["Proposal is explained in order", "Figures are not improvised", "Salesperson pauses after the ask", "Concern is isolated before returning to the manager"]}], "signoffCriteria": ["Prepares with the manager and understands every figure before presenting", "Uses consistent terminology and presentation order", "Explains price, trade, cash investment and payment options accurately", "Asks for a clear commitment and returns to the manager with useful information"]}'::jsonb)
