insert into public.knowledge_check_questions (step_id, position, question, options, answer_index)
values ((select id from public.steps where number = 9), 0, 'What should happen before the salesperson returns to the customer with numbers?', '["Review the proposal with the manager and understand every figure", "Round the figures to make them easier to present", "Prepare a discount to offer if the customer hesitates", "Ask the customer what payment they were hoping for"]'::jsonb, 0);

insert into public.knowledge_check_questions (step_id, position, question, options, answer_index)
values ((select id from public.steps where number = 9), 1, 'Why must payment and total price remain clear and separate?', '["So the presentation takes less time", "Focusing only on payment hides the full position; price, trade, cash investment and payment structure must each stay clear", "Because customers only care about the monthly payment", "So the manager can adjust the price later without questions"]'::jsonb, 1);

insert into public.knowledge_check_questions (step_id, position, question, options, answer_index)
values ((select id from public.steps where number = 9), 2, 'What should the salesperson bring back to the manager when the customer resists?', '["A lower figure the salesperson already promised", "A general sense that the customer is not happy", "A commitment or the specific concern, clarified and isolated", "A request to switch the customer to a cheaper unit"]'::jsonb, 2);

insert into public.knowledge_check_questions (step_id, position, question, options, answer_index)
values ((select id from public.steps where number = 9), 3, 'What should the salesperson do immediately after asking for commitment?', '["Keep explaining the value of the unit", "Offer to check with the manager for a better number", "Restate the proposal from the beginning", "Pause and give the customer time to process"]'::jsonb, 3);


-- Step 10: Close the Sale
insert into public.steps (number, slug, title, purpose, content, manager_content)
values (10, 'close-the-sale', 'Close the Sale', 'Turn readiness into a clear decision, resolve legitimate concerns and ask confidently for commitment.', '{"purpose": "Turn readiness into a clear decision, resolve legitimate concerns and ask confidently for commitment.", "learn": [{"heading": "What Success Looks Like", "body": "Distinguish a question, concern, objection and stall. Use the J|13 Objection Loop. Apply closing techniques at the appropriate moment. Use manager assistance without abandoning ownership of the customer."}, {"heading": "Execution Checklist", "body": "Ask for the commitment clearly. Listen to the complete response without interrupting. Clarify the real concern and isolate it from other issues. Respond with facts, value, options or the appropriate teammate. Confirm the concern is resolved. Reclose using the next appropriate commitment. Use a manager turnover when additional authority, perspective or relationship support is needed. Document the outcome and next step in the CRM."}, {"heading": "Self-Coaching", "body": "Watch for answering before understanding; clarify and isolate first. Watch for using a memorized comeback that ignores the customer; respond to the actual concern in the customer''s language. Watch for creating false scarcity; use only real availability or expiration information. Watch for giving up after the first no; respectfully clarify whether the answer is final or based on a solvable concern."}], "wordTracks": [{"label": "Direct close", "text": "You have selected the right unit and the structure works. Let''s complete the paperwork and prepare it for delivery."}, {"label": "Clarify", "text": "When you say you need to think about it, what specifically do you want to think through?"}, {"label": "Isolate", "text": "Other than [concern], is there anything else keeping you from moving forward?"}, {"label": "Confirm", "text": "Does that answer the concern completely?"}, {"label": "Reclose", "text": "Good. Then let''s move forward with [selected option]."}, {"label": "Manager TO", "text": "I want to make sure we have explored every responsible option. Let me bring [Manager] back in with the exact concern you shared."}], "practice": [{"title": "Practice Lab: Clarify Before You Answer", "instructions": "The customer says, \"I need to think about it.\" The salesperson must discover whether the issue is product fit, timing, another decision participant, trade or money. Success standard: the customer finishes speaking, at least two clarifying questions are used, the concern is isolated, the response matches the real issue and the salesperson recloses."}], "commitment": "On my next customer, I will apply this specific behavior."}'::jsonb, '{"number": 10, "managerCheckpoints": ["Make manager turnovers normal and professional, not dramatic", "Ask the salesperson what the customer said verbatim before entering", "Coach whether the objection was actually isolated and whether a clear reclose occurred"], "coachingNotes": ["Clarify and isolate first. Never answer before understanding", "Respond to the actual concern in the customer''s language instead of using a memorized comeback", "Use only real availability or expiration information. Never create false scarcity", "Respectfully clarify whether a no is final or based on a solvable concern instead of giving up after the first no", "Use the J|13 Objection Loop: Listen, Clarify, Respond, Confirm, Reclose", "Feel-Felt-Found can be useful when it is truthful and brief. Do not invent customer stories or use the technique to dismiss a legitimate concern", "Match the closing technique to the moment: assumptive, summary, alternative choice, sharp-angle, if-I-could-would-you and legitimate urgency. Never manufacture urgency"], "roleplayLabs": [{"title": "Clarify Before You Answer", "scenario": "The customer says I need to think about it. The salesperson must discover whether the issue is product fit, timing, another decision participant, trade or money. Roles: salesperson, customer with assigned hidden concern and observer.", "evaluationCriteria": ["Customer finishes speaking", "At least two clarifying questions are used", "Concern is isolated", "Response matches the real issue", "Salesperson recloses"]}], "signoffCriteria": ["Distinguishes a question, concern, objection and stall", "Uses the J|13 Objection Loop", "Applies closing techniques at the appropriate moment", "Uses manager assistance without abandoning ownership of the customer", "Documents the outcome and next step in the CRM"]}'::jsonb)
