  updated_at = now();

delete from public.knowledge_check_questions
  where step_id = (select id from public.steps where number = 10);

insert into public.knowledge_check_questions (step_id, position, question, options, answer_index)
values ((select id from public.steps where number = 10), 0, 'What are the five steps of the J|13 Objection Loop in order?', '["Listen, Clarify, Respond, Confirm, Reclose", "Ask, Argue, Adjust, Agree, Advance", "Clarify, Listen, Reclose, Respond, Confirm", "Present, Pause, Push, Pivot, Close"]'::jsonb, 0);

insert into public.knowledge_check_questions (step_id, position, question, options, answer_index)
values ((select id from public.steps where number = 10), 1, 'What makes urgency legitimate?', '["Telling the customer another buyer is coming in later", "Setting a deadline to force a same-day decision", "Using only real availability or expiration information", "Any urgency is acceptable if it closes the sale"]'::jsonb, 2);

insert into public.knowledge_check_questions (step_id, position, question, options, answer_index)
values ((select id from public.steps where number = 10), 2, 'When should a manager turnover occur?', '["Only after the customer has said no three times", "Whenever the salesperson wants a break", "Never, the salesperson should always close alone", "When additional authority, perspective or relationship support is needed"]'::jsonb, 3);

insert into public.knowledge_check_questions (step_id, position, question, options, answer_index)
values ((select id from public.steps where number = 10), 3, 'What should the salesperson do before responding to an objection?', '["Deliver the memorized comeback for that objection", "Listen to the complete response, then clarify and isolate the real concern", "Offer a discount to remove the objection", "Bring the manager in immediately"]'::jsonb, 1);


-- Step 11: Finance
insert into public.steps (number, slug, title, purpose, content, manager_content)
values (11, 'finance', 'Finance', 'Create a professional handoff that gives every qualified customer a complete opportunity to review protection and payment options.', '{"purpose": "Create a professional handoff that gives every qualified customer a complete opportunity to review protection and payment options.", "learn": [{"heading": "What Success Looks Like", "body": "Explain the purpose of the business office accurately. Complete a warm handoff with useful customer context. Avoid pre-selling or disqualifying finance products. Support cash-conversion conversations ethically and consistently."}, {"heading": "Execution Checklist", "body": "Confirm the deal is complete and required information is accurate. Contact the business manager according to dealership procedure before bringing the customer in. Brief the business manager on use, ownership priorities, decision participants, trade, timing and any questions already asked. Introduce the business manager by name and role. Explain that the manager will review paperwork, lender options when applicable and available ownership-protection products. Do not pre-sell price, coverage or eligibility. Do not say \"you won''t want that.\" Prepare the unit, accessories, fuel/charge, paperwork and delivery while finance completes the interview. After finance, complete an exit check and resolve any unanswered operational questions."}, {"heading": "Self-Coaching", "body": "Watch for calling finance \"the paperwork person\"; explain the business manager''s advisory and ownership role. Watch for promising a rate or payment; refer exact approval questions to finance. Watch for prejudging product interest; give every qualified customer a complete presentation. Watch for dropping the customer at finance and taking another customer; prepare delivery and complete the exit experience."}], "wordTracks": [{"label": "Set expectation", "text": "The next step is with [Business Manager], who will review the paperwork and all available ownership and payment options with you."}, {"label": "Warm introduction", "text": "[Customer], this is [Name], our business manager. [Name], [Customer] will use the unit for [use] and especially values [priority]."}, {"label": "Cash customer", "text": "Even though you plan to pay cash, [Name] will review the complete options so you can decide whether keeping some cash available makes sense for you."}, {"label": "Rate question", "text": "The business manager will compare the approved lender options and explain the exact rate and terms. I do not want to guess before that review is complete."}, {"label": "Product question", "text": "[Name] will explain eligibility, coverage, cost and exclusions so you can make an informed choice."}, {"label": "Post-finance check", "text": "Was everything explained clearly, and is there anything you want me to help clarify before delivery?"}], "practice": [{"title": "Practice Lab: The Warm Handoff", "instructions": "The customer is paying cash and says they do not need finance. The salesperson must explain the complete review without pressure or promising value. Success standard: the finance role is explained accurately, customer priorities are transferred, no product or approval is promised and the salesperson states what happens during finance."}], "commitment": "On my next customer, I will apply this specific behavior."}'::jsonb, '{"number": 11, "managerCheckpoints": ["Inspect whether every qualified customer receives the approved finance process", "Coach salespeople who quote rates or discourage products", "Use finance feedback to identify missing customer context in handoffs"], "coachingNotes": ["Explain the business manager''s advisory and ownership role. Never call finance the paperwork person", "Refer exact approval questions to finance. Never promise a rate or payment", "Give every qualified customer a complete presentation. Never prejudge product interest or say you won''t want that", "Prepare delivery and complete the exit experience instead of dropping the customer at finance and taking another customer", "Cash customers may still benefit from financing flexibility, protection products or liquidity; the conversation must remain factual and optional", "Brief the business manager on use, ownership priorities, decision participants, trade, timing and any questions already asked"], "roleplayLabs": [{"title": "The Warm Handoff", "scenario": "The customer is paying cash and says they do not need finance. The salesperson must explain the complete review without pressure or promising value. Roles: salesperson, customer, business manager and observer.", "evaluationCriteria": ["Finance role is explained accurately", "Customer priorities are transferred", "No product or approval is promised", "Salesperson states what happens during finance"]}], "signoffCriteria": ["Explains the purpose of the business office accurately", "Completes a warm handoff with useful customer context", "Avoids pre-selling or disqualifying finance products", "Supports cash-conversion conversations ethically and consistently"]}'::jsonb)
on conflict (number) do update set
  slug = excluded.slug,
  title = excluded.title,
  purpose = excluded.purpose,
  content = excluded.content,
  manager_content = excluded.manager_content,
  version = public.steps.version + 1,
  updated_at = now();

delete from public.knowledge_check_questions
  where step_id = (select id from public.steps where number = 11);

insert into public.knowledge_check_questions (step_id, position, question, options, answer_index)
values ((select id from public.steps where number = 11), 0, 'What information belongs in the finance brief?', '["The customer''s negotiating style and weak points", "Use, ownership priorities, decision participants, trade, timing and any questions already asked", "Only the final selling price", "The products the salesperson thinks the customer will buy"]'::jsonb, 1);

insert into public.knowledge_check_questions (step_id, position, question, options, answer_index)
values ((select id from public.steps where number = 11), 1, 'What should a salesperson say when asked for an exact rate?', '["Quote the best rate seen recently to keep the customer engaged", "Estimate a rate based on the customer''s appearance and trade", "Say the rate does not matter compared to the payment", "Explain that the business manager will compare approved lender options and give the exact rate rather than guessing"]'::jsonb, 3);

insert into public.knowledge_check_questions (step_id, position, question, options, answer_index)
values ((select id from public.steps where number = 11), 2, 'Why should cash customers still receive a complete finance review?', '["So they can decide whether keeping some cash available makes sense; every qualified customer deserves the complete presentation", "Because cash deals are not allowed at most dealerships", "So the dealership can add fees to the transaction", "To delay delivery while the unit is prepared"]'::jsonb, 0);

insert into public.knowledge_check_questions (step_id, position, question, options, answer_index)
values ((select id from public.steps where number = 11), 3, 'What should the salesperson do while the customer is in the finance office?', '["Take the next customer on the floor", "Sit in on the finance interview", "Prepare the unit, accessories, fuel/charge, paperwork and delivery", "Start the follow-up calls for the day"]'::jsonb, 2);


-- Step 12: Delivery & Follow-Up
insert into public.steps (number, slug, title, purpose, content, manager_content)
values (12, 'delivery-and-follow-up', 'Delivery & Follow-Up', 'Complete the ownership experience, prevent avoidable confusion and create the first repeat-and-referral opportunity.', '{"purpose": "Complete the ownership experience, prevent avoidable confusion and create the first repeat-and-referral opportunity.", "learn": [{"heading": "What Success Looks Like", "body": "Deliver the unit with a consistent checklist. Confirm paperwork, product operation and ownership resources. Set the first follow-up expectation before the customer leaves. Use a purposeful sold and unsold follow-up cadence."}, {"heading": "Execution Checklist", "body": "Complete the dealership delivery checklist before presenting the unit. Confirm accessories, cleanliness, fuel/charge, keys, manuals, registration items and promised work. Review operation, safety, maintenance, warranty basics and service contact information. Ask the customer to demonstrate critical controls when appropriate. Capture the delivery moment according to customer permission and dealership policy. Conduct an exit interview: clarity, unanswered questions, finance experience and referral opportunity. Set the first follow-up expectation and preferred communication channel. Complete CRM notes and all scheduled tasks before closing the record."}, {"heading": "Self-Coaching", "body": "Watch for rushing delivery because another customer arrived; complete the current customer experience or arrange an approved team handoff. Watch for giving a generic \"checking in\" follow-up; call with a specific purpose, update, question or piece of value. Watch for failing to record contact attempts; use the CRM as the system of record. Watch for continuing after a clear no-contact request; honor the request and follow policy."}], "wordTracks": [{"label": "Delivery agenda", "text": "Before you leave, we''ll verify the unit, review the controls and maintenance items, and make sure every promise is complete."}, {"label": "Teach-back", "text": "Show me how you would use [critical control] so I know I explained it clearly."}, {"label": "Exit check", "text": "Was everything explained clearly in the business office and throughout the process?"}, {"label": "First follow-up", "text": "I''ll contact you tomorrow to make sure the first use went smoothly. Do you prefer a call or text?"}, {"label": "Referral", "text": "Who do you know who would appreciate the same kind of help when they are ready?"}, {"label": "Unsold follow-up", "text": "I''m following up because you said [priority] was the most important. I have an update that may help you decide."}], "practice": [{"title": "Practice Lab: Delivery Teach-Back", "instructions": "The salesperson must deliver a unit, explain one safety-critical feature and use teach-back before setting the next-day follow-up. Success standard: the checklist is used, the critical feature is explained accurately, the customer demonstrates understanding and the follow-up time and channel are set."}], "commitment": "On my next customer, I will apply this specific behavior."}'::jsonb, '{"number": 12, "managerCheckpoints": ["Audit delivery checklists and promised-work completion", "Review prior-day deliveries and unsold follow-up every morning", "Listen for purposeful follow-up, not vague just checking in calls"], "coachingNotes": ["Complete the current customer experience or arrange an approved team handoff instead of rushing delivery because another customer arrived", "Call with a specific purpose, update, question or piece of value instead of a generic checking in follow-up", "Use the CRM as the system of record. Never count unlogged contact attempts", "Honor a clear no-contact request and follow policy", "Delivery is not the end of the sale. It is the beginning of ownership and the first proof that promises will be kept", "Continue follow-up until the customer buys, clearly declines, chooses another option, requests no contact or moves into the dealership''s long-term nurture plan"], "roleplayLabs": [{"title": "Delivery Teach-Back", "scenario": "The salesperson must deliver a unit, explain one safety-critical feature and use teach-back before setting the next-day follow-up. Roles: salesperson, customer and observer.", "evaluationCriteria": ["Checklist is used", "Critical feature is explained accurately", "Customer demonstrates understanding", "Follow-up time and channel are set"]}], "signoffCriteria": ["Delivers the unit with a consistent checklist", "Confirms paperwork, product operation and ownership resources", "Sets the first follow-up expectation before the customer leaves", "Uses a purposeful sold and unsold follow-up cadence recorded in the CRM"]}'::jsonb)
