insert into public.knowledge_check_questions (step_id, position, question, options, answer_index)
values ((select id from public.steps where number = 12), 0, 'Why is teach-back useful at delivery?', '["It confirms the customer understands critical controls and that the explanation was clear", "It saves the salesperson from explaining the controls", "It is a legal requirement for every delivery", "It gives the customer homework before they leave"]'::jsonb, 0);

insert into public.knowledge_check_questions (step_id, position, question, options, answer_index)
values ((select id from public.steps where number = 12), 1, 'When should the first sold follow-up be scheduled?', '["Within thirty days of delivery", "Only if the customer reports a problem", "The next day, with the time and preferred channel set before the customer leaves", "At the first scheduled maintenance visit"]'::jsonb, 2);

insert into public.knowledge_check_questions (step_id, position, question, options, answer_index)
values ((select id from public.steps where number = 12), 2, 'When should unsold follow-up stop or change?', '["After the second unanswered voicemail", "Never, persistence always wins", "When the manager reassigns the lead", "After a clear no-contact request, which must be honored while following policy"]'::jsonb, 3);

insert into public.knowledge_check_questions (step_id, position, question, options, answer_index)
values ((select id from public.steps where number = 12), 3, 'What makes a follow-up call better than a generic "checking in" call?', '["Calling at the same time every day", "A specific purpose, update, question or piece of value", "Keeping the call under thirty seconds", "Leaving the same voicemail on every attempt"]'::jsonb, 1);


-- Step 13: Prospecting & Referrals
insert into public.steps (number, slug, title, purpose, content, manager_content)
values (13, 'prospecting-and-referrals', 'Prospecting & Referrals', 'Create future opportunities through disciplined outreach, relationships, CRM activity and community visibility.', '{"purpose": "Create future opportunities through disciplined outreach, relationships, CRM activity and community visibility.", "learn": [{"heading": "What Success Looks Like", "body": "Build a daily prospecting rhythm. Use the CRM to manage outbound activity and long-term opportunities. Ask for referrals naturally throughout the ownership cycle. Apply the process to commercial and community prospects."}, {"heading": "Execution Checklist", "body": "Set daily activity goals for calls, two-way contacts, appointments, confirmations and shows. Work the highest-value lists first: prior-day unsold, active leads, missed appointments, orphan owners, previous customers, service opportunities and aged prospects. Use multiple approved channels: phone, text, email, video and social content. Ask for appointments with a specific reason and two time choices. Confirm appointments, record them in the CRM and appointment board, and involve the manager. Ask for referrals after value has been created, at delivery, after a positive follow-up and during ownership milestones. For commercial prospects, conduct a needs analysis, record equipment cycles and schedule a consistent follow-up plan. Review results daily and adjust the list, message or offer without abandoning the activity."}, {"heading": "Self-Coaching", "body": "Watch for only prospecting when traffic is slow; schedule protected daily outreach time. Watch for leaving generic voicemails with no reason to respond; reference the customer, unit, timing or useful update. Watch for counting unlogged activity; record the work in the CRM. Watch for asking for referrals before creating value; earn the referral through a strong experience, then ask directly."}], "wordTracks": [{"label": "Previous customer", "text": "I was reviewing your ownership file and wanted to ask how [unit] is working for you. Has anything changed in how you use it?"}, {"label": "Service opportunity", "text": "While your unit is here, would it be useful to see what your current trade position looks like?"}, {"label": "Appointment ask", "text": "I have two good times to show you the update: today at 4:30 or tomorrow at 10:15. Which works better?"}, {"label": "Confirmation", "text": "I have you scheduled for [time] with [unit] ready. I''ll confirm with you before you leave for the dealership."}, {"label": "Referral", "text": "Who in your circle is likely to need something similar in the next six months?"}, {"label": "Commercial", "text": "I''m not here to sell you something today. I want to understand your equipment cycle, current challenges and what would make a future conversation useful."}], "practice": [{"title": "Practice Lab: Appointment With a Reason", "instructions": "The salesperson receives an aged lead with no recent response. Create a call, voicemail, text and short video message that share one useful reason to reconnect. Success standard: the message is personal and relevant, the appointment ask is specific, two time choices are offered and the CRM next step is clear."}], "commitment": "On my next customer, I will apply this specific behavior."}'::jsonb, '{"number": 13, "managerCheckpoints": ["Set visible activity standards and inspect CRM quality, not only totals", "Confirm appointments personally and keep the appointment board current", "Review prior-day unsold customers and missed appointments every morning", "Recognize two-way contacts, shows and process quality as leading indicators"], "coachingNotes": ["Schedule protected daily outreach time instead of only prospecting when traffic is slow", "Reference the customer, unit, timing or useful update instead of leaving generic voicemails with no reason to respond", "Record the work in the CRM. Never count unlogged activity", "Earn the referral through a strong experience, then ask directly. Never ask before creating value", "Two-way contacts matter more than raw dials, but consistent activity creates those conversations", "For commercial prospects, conduct a needs analysis, record equipment cycles and schedule a consistent follow-up plan tied to the business cycle rather than generic monthly calls"], "roleplayLabs": [{"title": "Appointment With a Reason", "scenario": "The salesperson receives an aged lead with no recent response. Create a call, voicemail, text and short video message that share one useful reason to reconnect. Roles: salesperson, prospect and observer.", "evaluationCriteria": ["Message is personal and relevant", "Appointment ask is specific", "Two time choices are offered", "CRM next step is clear"]}], "signoffCriteria": ["Builds a daily prospecting rhythm with activity goals for calls, two-way contacts, appointments, confirmations and shows", "Uses the CRM to manage outbound activity and long-term opportunities", "Asks for referrals naturally throughout the ownership cycle", "Applies the process to commercial and community prospects"]}'::jsonb)
