insert into public.knowledge_check_questions (step_id, position, question, options, answer_index)
values ((select id from public.steps where number = 13), 0, 'Which prospecting lists should be worked first?', '["The oldest leads in the CRM regardless of status", "Random cold lists purchased from vendors", "The highest-value lists: prior-day unsold, active leads, missed appointments, orphan owners, previous customers, service opportunities and aged prospects", "Only internet leads from the last hour"]'::jsonb, 2);

insert into public.knowledge_check_questions (step_id, position, question, options, answer_index)
values ((select id from public.steps where number = 13), 1, 'What makes an appointment request specific?', '["A specific reason for the visit and two time choices", "Asking the customer to stop by whenever it is convenient", "Mentioning that the dealership is open seven days a week", "Promising the lowest price in the market"]'::jsonb, 0);

insert into public.knowledge_check_questions (step_id, position, question, options, answer_index)
values ((select id from public.steps where number = 13), 2, 'When are the best moments to ask for a referral?', '["During the first phone contact with a new lead", "After value has been created, at delivery, after a positive follow-up and during ownership milestones", "Only after the customer has bought at least twice", "Before presenting numbers so the customer feels invested"]'::jsonb, 1);

insert into public.knowledge_check_questions (step_id, position, question, options, answer_index)
values ((select id from public.steps where number = 13), 3, 'How should a salesperson open a first conversation with a commercial prospect?', '["Present the current commercial inventory and pricing", "Ask for the fleet manager''s budget for the year", "Offer a same-day demo of the newest unit", "Explain you are not there to sell today and that you want to understand their equipment cycle, current challenges and what would make a future conversation useful"]'::jsonb, 3);

commit;
